import nodemailer from "nodemailer";

/**
 * Sends real email from the app's own server code, via Gmail SMTP --
 * built 2026-10-31 for the Meeting Reminder Email tool (the user's own
 * request: "a tool in the app where the executive secretary can send
 * an email generated by the app through the associated gmail
 * account... directly from the app is fine. this all has to be free
 * within Vercel"). This is a genuinely separate thing from the Gmail
 * SMTP already configured inside the Supabase dashboard -- that
 * config is used internally by Supabase's own auth emails (password
 * reset, sign-up confirmation) and isn't reachable from this app's own
 * server code at all. Sending arbitrary app-generated email needs its
 * own credentials, read here from plain environment variables -- reuse
 * the exact same Gmail account/App Password already set up for Supabase
 * if that's simplest, or a different one; either way it's just a
 * second place the same (or a new) App Password gets pasted in.
 *
 * Free within Vercel, as asked: a Gmail account sends over SMTP at no
 * cost (up to Gmail's own daily sending limit -- 500/day for a regular
 * account), nodemailer adds no paid service, and one SMTP round trip
 * per send is nowhere near the Hobby plan's own serverless-function
 * limits.
 *
 * REQUIRED environment variables (set in Vercel -> Project -> Settings
 * -> Environment Variables, not committed anywhere):
 *   GMAIL_SMTP_USER          the full Gmail address, e.g. ward@gmail.com
 *   GMAIL_SMTP_APP_PASSWORD  a 16-character Gmail "App Password," NOT
 *                            the account's real sign-in password --
 *                            generate one at myaccount.google.com ->
 *                            Security -> 2-Step Verification -> App
 *                            Passwords (2-Step Verification must
 *                            already be turned on for this account;
 *                            the Supabase SMTP setup already needed
 *                            the exact same kind of password, so this
 *                            is the same process repeated once more).
 *
 * Server-only by construction (reads process.env directly, and every
 * caller is itself a "use server" action) -- never import this from a
 * Client Component.
 */

let cachedTransporter: ReturnType<typeof nodemailer.createTransport> | null = null;

function getTransporter() {
  const user = process.env.GMAIL_SMTP_USER;
  const pass = process.env.GMAIL_SMTP_APP_PASSWORD;
  if (!user || !pass) {
    throw new Error(
      "Email sending isn't configured yet -- set GMAIL_SMTP_USER and GMAIL_SMTP_APP_PASSWORD in Vercel's environment variables."
    );
  }

  if (!cachedTransporter) {
    cachedTransporter = nodemailer.createTransport({
      host: "smtp.gmail.com",
      port: 465,
      secure: true,
      auth: { user, pass },
    });
  }

  return { transporter: cachedTransporter, user };
}

export interface SendEmailOptions {
  /** Every real recipient goes in bcc, never to/cc -- a group reminder
   *  shouldn't expose everyone else's email address to everyone else. */
  bcc: string[];
  subject: string;
  text: string;
}

export async function sendEmail({ bcc, subject, text }: SendEmailOptions): Promise<void> {
  if (bcc.length === 0) throw new Error("No recipients to send to.");
  const { transporter, user } = getTransporter();

  // "to" is the sending account itself (never empty, and never one of
  // the real recipients) -- some mail providers flag/reject a message
  // with no visible "to" address at all, even when bcc is set.
  await transporter.sendMail({ from: user, to: user, bcc, subject, text });
}
